// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 读取渠道、模型、档位与任务分配
	// (GET /v1/admin/catalog)
	ReadAdminCatalog(ctx context.Context, request ReadAdminCatalogRequestObject) (ReadAdminCatalogResponseObject, error)
	// 证据驱动完成未知费用对账
	// (POST /v1/admin/invocations/{invocationId}/reconcile)
	ReconcileCharge(ctx context.Context, request ReconcileChargeRequestObject) (ReconcileChargeResponseObject, error)
	// 管理端查询费用账本
	// (GET /v1/admin/ledger)
	GetLedger(ctx context.Context, request GetLedgerRequestObject) (GetLedgerResponseObject, error)
	// 保存不可变模型身份版本
	// (PUT /v1/admin/models/{modelId})
	PutModel(ctx context.Context, request PutModelRequestObject) (PutModelResponseObject, error)
	// 读取历史固定价目
	// (GET /v1/admin/prices/{modelId})
	GetPriceBook(ctx context.Context, request GetPriceBookRequestObject) (GetPriceBookResponseObject, error)
	// 管理AI档位与费用限制
	// (PUT /v1/admin/profiles/{profileId})
	PutProfile(ctx context.Context, request PutProfileRequestObject) (PutProfileResponseObject, error)
	// CAS保存供应方
	// (PUT /v1/admin/providers/{providerId})
	PutProvider(ctx context.Context, request PutProviderRequestObject) (PutProviderResponseObject, error)
	// 加密存储密钥
	// (POST /v1/admin/providers/{providerId}/credentials)
	PutCredential(ctx context.Context, request PutCredentialRequestObject) (PutCredentialResponseObject, error)
	// 轮转新请求使用的密钥
	// (POST /v1/admin/providers/{providerId}/credentials/rotate)
	RotateCredential(ctx context.Context, request RotateCredentialRequestObject) (RotateCredentialResponseObject, error)
	// 取得本地维护屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放已授权维护屏障
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 读取费用限额配置
	// (GET /v1/budget-policy)
	ReadFeeBudgetPolicy(ctx context.Context, request ReadFeeBudgetPolicyRequestObject) (ReadFeeBudgetPolicyResponseObject, error)
	// 维护old费用开关与会话小时、网络5倍配置
	// (PUT /v1/budget-policy)
	PutFeeBudgetPolicy(ctx context.Context, request PutFeeBudgetPolicyRequestObject) (PutFeeBudgetPolicyResponseObject, error)
	// 刷新公开模型目录
	// (POST /v1/catalog:refresh)
	RefreshModelCatalog(ctx context.Context, request RefreshModelCatalogRequestObject) (RefreshModelCatalogResponseObject, error)
	// 计算可保守预留的最大费用
	// (POST /v1/cost-quotes)
	QuoteCost(ctx context.Context, request QuoteCostRequestObject) (QuoteCostResponseObject, error)
	// 接受统一AI调用
	// (POST /v1/inferences)
	CreateInference(ctx context.Context, request CreateInferenceRequestObject) (CreateInferenceResponseObject, error)
	// 读取调用状态
	// (GET /v1/inferences/{invocationId})
	ReadInference(ctx context.Context, request ReadInferenceRequestObject) (ReadInferenceResponseObject, error)
	// 贯穿取消调用
	// (POST /v1/inferences/{invocationId}/cancel)
	CancelInference(ctx context.Context, request CancelInferenceRequestObject) (CancelInferenceResponseObject, error)
	// 重连读取原流
	// (GET /v1/inferences/{invocationId}/events)
	ResumeInference(ctx context.Context, request ResumeInferenceRequestObject) (ResumeInferenceResponseObject, error)
	// 读取模型能力声明
	// (GET /v1/models)
	ReadModels(ctx context.Context, request ReadModelsRequestObject) (ReadModelsResponseObject, error)
	// 读取档位声明
	// (GET /v1/profiles)
	ReadProfiles(ctx context.Context, request ReadProfilesRequestObject) (ReadProfilesResponseObject, error)
	// 显式测试连接
	// (POST /v1/providers/{providerId}:probe)
	CreateConnectionProbe(ctx context.Context, request CreateConnectionProbeRequestObject) (CreateConnectionProbeResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出安全watermark快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
	// 读取任务模型映射
	// (GET /v1/task-assignments)
	ReadTaskAssignments(ctx context.Context, request ReadTaskAssignmentsRequestObject) (ReadTaskAssignmentsResponseObject, error)
	// 超管维护单任务模型覆盖
	// (PUT /v1/task-assignments/{taskId})
	PutTaskAssignment(ctx context.Context, request PutTaskAssignmentRequestObject) (PutTaskAssignmentResponseObject, error)
	// 免费读取QA任务配置能力
	// (POST /v1/task-availability:read)
	ReadTaskAvailability(ctx context.Context, request ReadTaskAvailabilityRequestObject) (ReadTaskAvailabilityResponseObject, error)
	// 跨服务读取权威费用状态
	// (GET /v1/usage)
	QueryUsage(ctx context.Context, request QueryUsageRequestObject) (QueryUsageResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

